const Q = ($('Hook').first().json.query) || {};
const q = String(Q.q || '').trim();
const H = this.helpers;
const UA = { 'User-Agent': 'CBS-Operations-Hub/1.0 (contact4@example.com)' };
async function get(url, headers){ return await H.httpRequest({ method:'GET', url, headers: headers||{}, json:true, timeout:25000 }); }
function miles(a,b,c,d){ const R=3958.8, r=x=>x*Math.PI/180; const dl=r(c-a), dn=r(d-b); const h=Math.sin(dl/2)**2+Math.cos(r(a))*Math.cos(r(c))*Math.sin(dn/2)**2; return 2*R*Math.asin(Math.sqrt(h)); }
if (!q) return [{ json:{ ok:false, error:'Add the site address first.' } }];

let lat=null, lon=null, where='';
const m = q.toUpperCase().match(/\b([A-Z]{1,2}\d[A-Z\d]?)\s*(\d[A-Z]{2})\b/);
if (m) {
  const pc = m[1]+' '+m[2];
  try { const r = await get('https://api.postcodes.io/postcodes/'+encodeURIComponent(pc)); if (r && r.result) { lat=r.result.latitude; lon=r.result.longitude; where=pc; } } catch(e) {}
  if (lat==null) { try { const r = await get('https://api.postcodes.io/outcodes/'+encodeURIComponent(m[1])); if (r && r.result) { lat=r.result.latitude; lon=r.result.longitude; where=m[1]; } } catch(e) {} }
}
if (lat==null) {
  const parts = q.split(/[,\n]+/).map(s=>s.trim()).filter(Boolean);
  const tries = []; for (let i=0;i<parts.length;i++) tries.push(parts.slice(i).join(', '));
  const words = q.replace(/[,\n]+/g,' ').trim().split(/\s+/); if (words.length>2) { tries.push(words.slice(-2).join(' ')); tries.push(words.slice(-1)[0]); }
  for (const t of tries) {
    if (lat!=null || t.length<3) continue;
    try { const r = await get('https://nominatim.openstreetmap.org/search?format=json&countrycodes=gb&limit=1&q='+encodeURIComponent(t), UA); if (r && r[0]) { lat=Number(r[0].lat); lon=Number(r[0].lon); where=t; } } catch(e) {}
  }
}
if (lat==null) return [{ json:{ ok:false, error:"Couldn't place that address. Add the site postcode and try again." } }];

const ERR=[];
async function overpass(radius){
  const ql = '[out:json][timeout:20];nwr["amenity"="hospital"]["emergency"="yes"](around:'+radius+','+lat+','+lon+');out center tags;';
  const urls = ['https://overpass-api.de/api/interpreter','https://overpass.private.coffee/api/interpreter','https://maps.mail.ru/osm/tools/overpass/api/interpreter','https://overpass.kumi.systems/api/interpreter'];
  for (const u of urls) {
    try { let r = await H.httpRequest({ method:'GET', url:u+'?data='+encodeURIComponent(ql), headers:UA, timeout:25000 }); if (typeof r==='string') r=JSON.parse(r); if (r && Array.isArray(r.elements)) return r.elements; ERR.push(u+': no elements'); } catch(e) { ERR.push(u+': '+String(e.message||e).slice(0,160)); }
  }
  return null;
}
let els = await overpass(40000);
if (els && !els.length) els = await overpass(80000);
if (els === null) return [{ json:{ ok:false, error:'The hospital lookup service is busy. Try again in a minute.', debug:ERR } }];

const seen = {};
let list = els.map(e => {
  const t = e.tags||{}; const la = e.lat!=null?e.lat:(e.center&&e.center.lat); const lo = e.lon!=null?e.lon:(e.center&&e.center.lon);
  if (la==null || !t.name) return null;
  return { name:t.name, lat:la, lon:lo, street:[t['addr:housenumber'],t['addr:street']].filter(Boolean).join(' '), town:t['addr:city']||t['addr:town']||'', postcode:t['addr:postcode']||'', phone:t.phone||t['contact:phone']||'', dist:miles(lat,lon,la,lo) };
}).filter(Boolean).sort((a,b)=>a.dist-b.dist).filter(h => { const k=h.name.toLowerCase(); if (seen[k]) return false; seen[k]=1; return true; }).slice(0,3);

const need = list.filter(h=>!h.postcode);
if (need.length) {
  try {
    const r = await H.httpRequest({ method:'POST', url:'https://api.postcodes.io/postcodes', body:{ geolocations: need.map(h=>({ latitude:h.lat, longitude:h.lon, limit:1, radius:1000 })) }, json:true, timeout:20000 });
    (r.result||[]).forEach((x,i)=>{ const p = x.result && x.result[0]; if (p) { need[i].postcode=p.postcode; if(!need[i].town) need[i].town=p.admin_district||''; } });
  } catch(e) {}
}
list = list.map(h => {
  const addr = [h.street, h.town, h.postcode].filter(Boolean).join(', ');
  const mi = Math.round(h.dist*10)/10;
  return { name:h.name, address:addr, phone:h.phone, miles:mi,
    text: h.name+(addr?', '+addr:'')+' ('+mi+' miles in a straight line)',
    maps: 'https://www.google.com/maps/dir/?api=1&origin='+lat+','+lon+'&destination='+encodeURIComponent(h.name+(h.postcode?' '+h.postcode:'')) };
});
return [{ json:{ ok:true, from:where, lat, lon, hospitals:list } }];

